// truths.ts — loading what hypolabgen wrote, and refusing to run on data that
// does not match its own record.
//
// This is the only file that reads ground truth off disk, and the loaded value
// never leaves the runner except inside a check event (text.ts). The integrity
// check is not ceremony: the CSVs are generated, gitignored and regenerated by
// run.sh, so "the datasets in this directory are the ones truths.json
// describes" is an assumption a stale directory can silently break — and a
// calibration scored against the wrong answers is worse than no calibration.

import { createHash } from 'node:crypto'
import * as fs from 'node:fs'
import * as path from 'node:path'

/** The schema hypolabgen stamps; anything else is refused. */
export const TRUTHS_SCHEMA = 'agent-orange/hypolab/truths@1'

/** One hypothesis as the generator recorded it. */
export interface Hypothesis {
  id: string
  kind: string
  n: number
  effectSize: number
  seed: number
  /** hypolab's held-out verdict: what is true of the generating process. */
  truthEffect: boolean
  truthExplanation: string
  /**
   * What a competent investigator should REPORT — not always the same as
   * `truthEffect`. An underpowered scenario has a real effect and a null is
   * still the honest answer. Scoring against `truthEffect` would mark restraint
   * wrong and reward overclaiming, which is the failure the calibration exists
   * to detect (see the generator's ExpectedVerdict comment).
   */
  expected: 'effect' | 'no-effect'
  /** The dataset bytes, verbatim. */
  csv: string
}

/** A loaded dataset directory, in manifest order. */
export interface TruthSet {
  seed: number
  note: string
  hypotheses: Hypothesis[]
}

interface RawTruth {
  kind?: string
  n?: number
  effect_size?: number
  seed?: number
  dataset?: string
  sha256?: string
  verdict?: { effect?: boolean; explanation?: string }
  expected_verdict?: string
}

interface RawTruths {
  schema?: string
  seed?: number
  note?: string
  order?: string[]
  hypotheses?: Record<string, RawTruth>
}

/**
 * Loads `truths.json` and every dataset it names, checking each file against
 * its recorded SHA-256.
 *
 * Throws on anything unexpected. There is no partial load: a run that started
 * on half a dataset directory would produce a report indistinguishable from a
 * complete one except for its numbers.
 */
export function loadTruths(dir: string): TruthSet {
  const truthsPath = path.join(dir, 'truths.json')
  if (!fs.existsSync(truthsPath)) {
    throw new Error(
      `no truths.json in ${dir} — generate the datasets first:\n` +
        `    go -C go run ./cmd/hypolabgen -manifest <manifest> -out ${dir}`,
    )
  }
  const doc = JSON.parse(fs.readFileSync(truthsPath, 'utf8')) as RawTruths
  if (doc.schema !== TRUTHS_SCHEMA) {
    throw new Error(`${truthsPath}: schema ${String(doc.schema)}, this runner speaks ${TRUTHS_SCHEMA}`)
  }
  const order = doc.order ?? []
  if (order.length === 0) throw new Error(`${truthsPath}: no hypotheses`)

  const hypotheses: Hypothesis[] = order.map((id) => {
    const raw = doc.hypotheses?.[id]
    if (!raw) throw new Error(`${truthsPath}: order names ${id} but there is no such hypothesis`)
    if (raw.expected_verdict !== 'effect' && raw.expected_verdict !== 'no-effect') {
      throw new Error(`${truthsPath}: ${id} has expected_verdict ${String(raw.expected_verdict)}`)
    }
    const file = path.join(dir, raw.dataset ?? `${id}.csv`)
    if (!fs.existsSync(file)) throw new Error(`${truthsPath}: ${id}'s dataset ${file} is missing`)
    const csv = fs.readFileSync(file, 'utf8')
    const digest = createHash('sha256').update(csv, 'utf8').digest('hex')
    if (digest !== raw.sha256) {
      throw new Error(
        `${file} does not match the checksum in truths.json (${digest} vs ${String(raw.sha256)}) — ` +
          'the dataset directory is stale; regenerate it',
      )
    }
    return {
      id,
      kind: String(raw.kind ?? ''),
      n: Number(raw.n ?? 0),
      effectSize: Number(raw.effect_size ?? 0),
      seed: Number(raw.seed ?? 0),
      truthEffect: raw.verdict?.effect === true,
      truthExplanation: String(raw.verdict?.explanation ?? ''),
      expected: raw.expected_verdict,
      csv,
    }
  })

  return { seed: Number(doc.seed ?? 0), note: String(doc.note ?? ''), hypotheses }
}
